const raw = String($input.first().json.stdout || '').trim();
if (!raw) throw new Error('No output from AD-Password-Expiry.ps1');

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  const m = raw.match(/\{[\s\S]*\}/);
  if (!m) throw new Error('No JSON in script output: ' + raw.slice(0, 200));
  try { parsed = JSON.parse(m[0]); }
  catch (e2) { throw new Error('Bad JSON from script: ' + raw.slice(0, 200)); }
}
if (parsed.Error) throw new Error('Script error: ' + parsed.Error);

let data = parsed.Data || parsed.data || [];
if (!Array.isArray(data)) data = [data];

// Keep ONLY users whose password has already expired
const expired = data.filter(u => {
  const expiryText = u.ExpiryDate || u.expiryDate || '';
  if (expiryText === 'Pending Change' || expiryText === 'Never expires') return false;
  return parseInt(u.DaysUntilExpiry ?? u.daysUntilExpiry ?? 1) <= 0;
});

// No expired users -> no items -> the rest of the flow does not run
return expired.map(u => ({
  json: {
    username: u.Username || u.username || '',
    fullname: u.FullName || u.fullname || '',
    email: u.Email || u.email || '',
    expiryDate: u.ExpiryDate || u.expiryDate || '',
    daysUntilExpiry: parseInt(u.DaysUntilExpiry ?? u.daysUntilExpiry ?? 0)
  }
}));

// Runs once for all items: one message per 12 users
const expired = $input.all()
  .map(i => i.json)
  .filter(u => u.username)
  .sort((a, b) => a.daysUntilExpiry - b.daysUntilExpiry);

const chunkSize = 12;
const results = [];
for (let i = 0; i < expired.length; i += chunkSize) {
  const chunk = expired.slice(i, i + chunkSize);
  const blocks = [];
  blocks.push({
    type: "header",
    text: {
      type: "plain_text",
      text: expired.length <= chunkSize
        ? `🔑 Expired Passwords (${expired.length} User${expired.length === 1 ? '' : 's'})`
        : `🔑 Expired Passwords (${i + 1}-${Math.min(i + chunkSize, expired.length)} of ${expired.length})`,
      emoji: true
    }
  });
  blocks.push({ type: "divider" });
  chunk.forEach((user) => {
    blocks.push({
      type: "section",
      text: {
        type: "mrkdwn",
        text: `👤 *${user.fullname || 'Unknown'}* (\`${user.username}\`)\n📧 ${user.email || 'N/A'} | 📅 Expired: ${user.expiryDate} | ❌ EXPIRED`
      }
    });
    blocks.push({
      type: "actions",
      elements: [{
        type: "button",
        text: { type: "plain_text", text: "Reset Password", emoji: true },
        style: "danger",
        action_id: `btn_reset_password_${user.username}`,
        value: user.username
      }]
    });
    blocks.push({ type: "divider" });
  });
  blocks.push({
    type: "context",
    elements: [{ type: "mrkdwn", text: "🤖 Automated with AD Admin Bot" }]
  });
  results.push({ json: { blocks: JSON.stringify(blocks), batchIndex: results.length } });
}
return results;

const item = $input.first();
const headers = item.json.headers || {};
const sig = headers['x-slack-signature'] || '';
const ts = headers['x-slack-request-timestamp'] || '';

let raw = '';
try {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  raw = buf.toString('utf8');
} catch (e) {
  raw = '';
}

// Slack signs: v0:<timestamp>:<raw body>
const base = (sig && ts && raw) ? `v0:${ts}:${raw}` : 'invalid';

return [{ json: { body: item.json.body, sig, ts, base } }];

// ---- EDIT THIS ----
const ALLOWED_USER_IDS = ['U08AYDL2FQD']; // Slack member IDs allowed to click the buttons
// -------------------

const item = $input.first().json;
let verified = false;
let reason = '';

try {
  if (!item.sig || !item.ts || item.base === 'invalid') throw new Error('Missing Slack signature headers');
  if (Math.abs(Date.now() / 1000 - Number(item.ts)) > 300) throw new Error('Request too old');

  const expected = 'v0=' + item.hmac;
  const given = String(item.sig);

  // constant-time comparison
  let diff = expected.length ^ given.length;
  for (let i = 0; i < Math.max(expected.length, given.length); i++) {
    diff |= (expected.charCodeAt(i) || 0) ^ (given.charCodeAt(i) || 0);
  }
  if (diff !== 0) throw new Error('Invalid signature');

  const payload = JSON.parse(item.body.payload);
  if (!ALLOWED_USER_IDS.includes(payload.user.id)) throw new Error('User not allowed: ' + payload.user.id);

  verified = true;
} catch (e) {
  reason = e.message;
}

return [{ json: { body: item.body, verified, reason } }];

const payload = JSON.parse($input.first().json.body.payload);
const action = payload.actions[0];
// Only allow safe AD username characters
const username = String(action.value || '').replace(/[^a-zA-Z0-9._-]/g, '');

return {
  action_id: String(action.action_id).startsWith('btn_reset_password') ? 'btn_reset_password' : action.action_id,
  username: username,
  adminUser: payload.user.name,
  channel: (payload.channel && payload.channel.id) || (payload.container && payload.container.channel_id) || '',
  ts: (payload.container && payload.container.message_ts) || (payload.message && payload.message.ts) || '',
  blockId: action.block_id || '',
  blocksJson: JSON.stringify((payload.message && payload.message.blocks) || [])
};

const r = $input.first().json;
const out = String(r.stdout || '').trim();
const err = String(r.stderr || r.error || '').trim();

let data = null;
const m = out.match(/\{[\s\S]*\}/);
try { data = m ? JSON.parse(m[0]) : null; } catch (e) { data = null; }

if (data && data.Status === 'Success' && data.Password) {
  return [{ json: { ok: true, username: data.Username, password: data.Password } }];
}

const detail = (data && data.Message) || err || out || 'No output from script';
return [{ json: { ok: false, detail: String(detail).slice(0, 500) } }];

const click = $('Parse Click').first().json;
const r = $input.first().json;

const when = new Date().toLocaleString('en-GB', {
  timeZone: 'Asia/Jerusalem', day: 'numeric', month: 'numeric', year: 'numeric',
  hour: 'numeric', minute: '2-digit', hour12: true
});

let blocks = [];
try { blocks = JSON.parse(click.blocksJson || '[]'); } catch (e) { blocks = []; }

const resultBlock = r.ok
  ? {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: '✅ *Password reset* by *' + click.adminUser + '* • ' + when +
              '\n🔑 New temp password: `' + r.password + '`' +
              '\n⚠️ _User must change it at next login._'
      }
    }
  : {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: '❌ *Reset failed* (requested by *' + click.adminUser + '*) • ' + when +
              '\n```' + r.detail + '```'
      }
    };

// Find the clicked user's button row and put the result right there
const idx = blocks.findIndex(b => b.block_id === click.blockId);
let updated = null;
if (idx >= 0) {
  updated = blocks.slice();
  if (r.ok) updated.splice(idx, 1, resultBlock);   // replace the button with the result
  else updated.splice(idx + 1, 0, resultBlock);    // keep the button (retry) and show the error under it
}

return [{
  json: {
    ok: r.ok,
    username: click.username,
    password: r.password || '',
    detail: r.detail || '',
    channel: click.channel,
    ts: click.ts,
    blocks: updated ? JSON.stringify(updated) : '',
    canUpdate: !!(updated && click.channel && click.ts)
  }
}];

