const raw = String($input.first().json.stdout || '').trim();
if (!raw) throw new Error('No output from Get-ADLockedUsers.ps1');

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  const m = raw.match(/\{[\s\S]*\}/);
  if (!m) throw new Error('No JSON in script output: ' + raw.slice(0, 200));
  try { parsed = JSON.parse(m[0]); }
  catch (e2) { throw new Error('Bad JSON from script: ' + raw.slice(0, 200)); }
}
if (parsed.Error) throw new Error('Script error: ' + parsed.Error);

let data = parsed.Data || parsed.data || [];
if (!Array.isArray(data)) data = [data];
const users = data.filter(u => u.Username || u.username);

// Remember who we already alerted, so a user who stays locked is not announced every minute.
// When a user is no longer locked we forget them, so a NEW lockout alerts again.
const staticData = $getWorkflowStaticData('global');
staticData.lockedAlerted = staticData.lockedAlerted || {};
const stillLocked = new Set(users.map(u => String(u.Username || u.username).toLowerCase()));
for (const k of Object.keys(staticData.lockedAlerted)) {
  if (!stillLocked.has(k)) delete staticData.lockedAlerted[k];
}

const fmt = (value) => {
  const d = new Date(value);
  if (!value || isNaN(d)) return 'Unknown';
  const p = Object.fromEntries(
    new Intl.DateTimeFormat('en-GB', {
      timeZone: 'Asia/Jerusalem',
      day: 'numeric', month: 'numeric', year: 'numeric',
      hour: 'numeric', minute: '2-digit', hour12: true
    }).formatToParts(d).map(x => [x.type, x.value])
  );
  return `${p.day}.${p.month}.${p.year} ${p.hour}:${p.minute} ${String(p.dayPeriod || '').toUpperCase()}`;
};

const fresh = users.filter(u => !staticData.lockedAlerted[String(u.Username || u.username).toLowerCase()]);
fresh.forEach(u => { staticData.lockedAlerted[String(u.Username || u.username).toLowerCase()] = Date.now(); });

// No new lockouts -> no items -> the rest of the flow does not run
return fresh.map(u => ({
  json: {
    username: u.Username || u.username,
    fullname: u.FullName || u.fullname || '',
    email: u.Email || u.email || '',
    computer: u.CallerComputer || u.computer || 'UNKNOWN',
    lockedAt: fmt(u.LockoutTime || u.lockoutTime)
  }
}));

// Runs once for all items: one message per 12 users
const locked = $input.all().map(i => i.json).filter(u => u.username);

const chunkSize = 12;
const results = [];
for (let i = 0; i < locked.length; i += chunkSize) {
  const chunk = locked.slice(i, i + chunkSize);
  const blocks = [];
  blocks.push({
    type: "header",
    text: {
      type: "plain_text",
      text: locked.length <= chunkSize
        ? `🚨 AD Lockout Detected (${locked.length} User${locked.length === 1 ? '' : 's'})`
        : `🚨 AD Lockout Detected (${i + 1}-${Math.min(i + chunkSize, locked.length)} of ${locked.length})`,
      emoji: true
    }
  });
  blocks.push({ type: "divider" });
  chunk.forEach((user) => {
    blocks.push({
      type: "section",
      text: {
        type: "mrkdwn",
        text: `👤 *${user.fullname || 'Unknown'}* (\`${user.username}\`)\n💻 Workstation: \`${user.computer}\` | 📅 Locked at: ${user.lockedAt}`
      }
    });
    blocks.push({
      type: "actions",
      elements: [{
        type: "button",
        text: { type: "plain_text", text: "Unlock Account", emoji: true },
        style: "primary",
        action_id: `btn_unlock_${user.username}`,
        value: user.username
      }]
    });
    blocks.push({ type: "divider" });
  });
  blocks.push({
    type: "context",
    elements: [{ type: "mrkdwn", text: "🤖 Automated with AD Admin Bot" }]
  });
  results.push({ json: { blocks: JSON.stringify(blocks), batchIndex: results.length } });
}
return results;

